import pandas as pd
import polars as pl
import narwhals as nw


@nw.narwhalify
def add_total(df):
    return df.with_columns(
        total=nw.col("price") * nw.col("quantity")
    )


# Test with pandas
df_pandas = pd.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 4]
})
result_pandas = add_total(df_pandas)
print("Pandas result:")
print(result_pandas)
print()

# Test with polars
df_polars = pl.DataFrame({
    "price": [10, 20, 30],
    "quantity": [2, 3, 4]
})
result_polars = add_total(df_polars)
print("Polars result:")
print(result_polars)
